// === n8n Code Node: Prepare Conversation History safely ===

const FETCH_CONVERSATION_NODE_NAME = "Fetch Conversation History";
const PARSE_INPUT_NODE_NAME = "Parse Input";

let fetchConversationNodeOutput = [];
try {
    const fetchRes = $(FETCH_CONVERSATION_NODE_NAME).all();
    if (fetchRes && fetchRes.length > 0) {
        fetchConversationNodeOutput = fetchRes.map(item => item.json);
    }
} catch (e) {
    fetchConversationNodeOutput = [];
}

let parseInputNodeOutput = [{ message: "", phone: "", name: "", channel: "", id: null }];
try {
    const parseRes = $(PARSE_INPUT_NODE_NAME).all();
    if (parseRes && parseRes.length > 0) {
        parseInputNodeOutput = parseRes.map(item => item.json);
    }
} catch (e) {
    // Fallback
}

const conversation = fetchConversationNodeOutput.length > 0 ? fetchConversationNodeOutput[0] : null;

// 5️⃣ تحضير الـ History مع حماية ضد [object Object] القديمة
let history = [];
if (conversation && conversation.history) {
    let rawHistory = conversation.history;

    if (typeof rawHistory === 'object' && rawHistory !== null) {
        history = Array.isArray(rawHistory) ? rawHistory : [rawHistory];
    } else if (typeof rawHistory === 'string' && rawHistory.trim() !== "" && rawHistory !== "[object Object]") {
        try {
            history = JSON.parse(rawHistory);
            if (!Array.isArray(history)) history = [];
        } catch (e) {
            history = [];
        }
    }
}

const message = (parseInputNodeOutput[0].message || "")
    .replace(/[\n\r]/g, " ")
    .normalize("NFKD")
    .trim();

if (message) {
    history.push({
        role: "user",
        content: message,
        timestamp: new Date().toISOString(),
    });
}

const isNewConversation = (conversation && conversation.id && conversation.history !== "[object Object]") ? false : true;
const conversationId = (conversation && conversation.id) ? conversation.id : null;

return [
    {
        json: {
            phone: parseInputNodeOutput[0].phone || "",
            name: parseInputNodeOutput[0].name || "",
            channel: parseInputNodeOutput[0].channel || "",
            id: parseInputNodeOutput[0].id || null, 
            history,               // غاتخرج Array نقي 100%
            isNewConversation,     
            conversationId,        
        },
    },
];

// Access data from webhook body
const body = $json["body"] || {};  // webhook test kay7taj body
const message = body["message"] || "No message";
const phone = body["phone"] || "unknown";
const name = body["name"] || "unknown";
const channel = body["channel"] || "unknown";
return [
  {
    json: { message, phone, name, channel}
  }
];

// 1. كنجيبو الـ data من الـ AI
const aiResponse = $('AI Intent Detection').item.json.choices[0].message.content;
let parsedData;

try {
    parsedData = JSON.parse(aiResponse);
} catch (e) {
    parsedData = { intent: "unknown", parameters: {} };
}

// 2. كنجيبو الـ data من الداتابيز (باش ما نساوش)
const dbData = $('Fetch Conversation History').last()?.json?.last_parameters || {};

// 3. الدمج د الداتا (الأسبقية للـ AI، وإيلا null ناخدو من DB)
let params = {
    guests: parsedData.parameters?.guests || dbData.guests || null,
    checkin_date: parsedData.parameters?.checkin_date || dbData.checkin_date || null,
    checkout_date: parsedData.parameters?.checkout_date || dbData.checkout_date || null
};

// 4. "هنا كاين البلان": حنا اللي كنحددو الـ Status
// واخا الـ AI يقول incomplete، إيلا كان الكود كيلقى التواريخ، غانردوها complete بزز!
const isComplete = (params.checkin_date && params.checkout_date && params.guests);

return [{
    json: {
        status: isComplete ? "complete" : "incomplete",
        intent: parsedData.intent || "book_room",
        parameters: params
    }
}];

const rooms = $input.all().map(r => r.json);
const list = rooms.map(r => 
  `🛏 ${r.type} — ${r.room_number} — ${r.price_per_night} MAD/night`
).join('\n');

return [{ json: { 
  reply: `Available rooms:\n${list}`,
  intent: 'list_rooms'
}}];

