JSON.stringify((function() {
  // 1. تحضير الـ History الجديد (نفس اللوجيك السيرفر)
  let currentHistory = $('AI Intent Detection').item.json.history;
  if (typeof currentHistory === 'string' && currentHistory.trim() !== "") {
    try { currentHistory = JSON.parse(currentHistory); } catch(e) { currentHistory = []; }
  }
  if (!Array.isArray(currentHistory)) currentHistory = [];

  currentHistory.push({
    "role": "assistant",
    "content": $json.reply || "",
    "timestamp": new Date().toISOString()
  });

  const isNew = $('Prepare Conversation History').item.json.isNewConversation;

  // 2. يلا كانت محادثة جديدة، كنصيفطو كاع الداتا باش تتكريا نقيّة
  if (isNew) {
    return {
      "phone": $('Prepare Conversation History').item.json.phone,
      "name": $('Prepare Conversation History').item.json.name,
      "channel": $('Prepare Conversation History').item.json.channel,
      "history": currentHistory,
      "status": "incomplete"
    };
  } 

  // 3. يلا كانت قديمة، كنديرو PATCH للـ history بوحدو
  return {
    "history": currentHistory
  };
})())
}}

