const message = $('Parse Input').first().json.message;

const systemPrompt = "You are a hotel booking assistant. You have access to the full conversation history. RULES: If user confirms (yes/ok/book it) look at history for dates and guests already mentioned, use them directly, never ask again. Detect intent: book_room, check_availability, list_rooms, cancel_booking, get_info, unknown. Return JSON only: {\"status\":\"complete\",\"intent\":\"book_room\",\"parameters\":{\"guests\":2,\"checkin_date\":\"2026-05-28\",\"checkout_date\":\"2026-05-30\",\"room_type\":null},\"reply\":null}";

const messages = [
  { role: "system", content: systemPrompt },
  ...history,
  { role: "user", content: message }
];

const body = {
  model: "gpt-oss-120b",
  messages: messages
};

return [{ json: { body: JSON.stringify(body) }}];

const historyRaw = $('Fetch Conversation History').first().json.history || [];
const message = $('Parse Input').first().json.message;

const systemPrompt = "You are a hotel booking assistant. You have access to the full conversation history. RULES: If user confirms (yes/ok/book it) look at history for dates and guests already mentioned, use them directly, never ask again. Detect intent: book_room, check_availability, list_rooms, cancel_booking, get_info, unknown. Return JSON only: {\"status\":\"complete\",\"intent\":\"book_room\",\"parameters\":{\"guests\":2,\"checkin_date\":\"2026-05-28\",\"checkout_date\":\"2026-05-30\",\"room_type\":null},\"reply\":null}";

const history = historyRaw.map(h => ({
  role: h.role,
  content: h.content
}));

const lastMsg = history[history.length - 1];
const alreadyAdded = lastMsg && lastMsg.role === 'user' && lastMsg.content === message;

const messages = [
  { role: "system", content: systemPrompt },
  ...history,
  ...(alreadyAdded ? [] : [{ role: "user", content: message }])
];

const body = {
  model: "gpt-oss-120b",
  messages: messages
};

return [{ json: { body: JSON.stringify(body) }}];
